begin;
create schema ca_feature_check;
create function ca_feature_check.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end $$;
grant usage on schema ca_feature_check to authenticated;grant execute on function ca_feature_check.assert(boolean,text) to authenticated;
insert into public.congregations(id,name,status) values('feature-check-a','Feature test A','active'),('feature-check-b','Feature test B','active');
insert into public.congregation_access(cong_id,email,role,is_assistant) values('feature-check-a','combined@example.com','field_service',false),('feature-check-a','combined@example.com','oclm',true),('feature-check-a','assistant@example.com','oclm',true);
do $$ begin begin insert into public.congregation_access(cong_id,email,role,is_assistant) values('feature-check-a','bad@example.com','admin',true);raise exception 'Main admin assistant accepted';exception when check_violation then null;end;end $$;
set request.jwt.claims='{"email":"combined@example.com","app_metadata":{"provider":"google"}}';set role authenticated;
select ca_feature_check.assert(public.ca_has_role('feature-check-a',array['field_service']) and public.ca_has_role('feature-check-a',array['oclm']),'one Google identity has two assigned sections');
select ca_feature_check.assert(not public.ca_has_role('feature-check-a',array['attendance']) and not public.ca_is_congregation_admin('feature-check-a'),'combined role does not get attendance or administration');
reset role;set request.jwt.claims='{"email":"assistant@example.com","app_metadata":{"provider":"google"}}';set role authenticated;
select ca_feature_check.assert(public.ca_has_role('feature-check-a',array['oclm']) and not public.ca_has_role('feature-check-a',array['field_service']) and not public.ca_is_congregation_admin('feature-check-a'),'OCLM assistant is confined to OCLM');
select set_config('ca_feature.snapshot_token',(public.upsert_oclm_public_snapshot('feature-check-a','{"kind":"midweek","v":2,"defaultWeek":"2026-W44","publishedWeeks":["2026-W44"],"additionalDuties":[{"id":"Duty_0123456789abcdef0123456789abcdef","name":"Microphones","section":"AV","slots":2,"privateNote":"DUTY SECRET"},{"id":"unsafe","name":"INVALID DUTY","slots":99}],"assignments":{"2026-W44":{"MeetingStart":{"customTitle":"19:00"},"OpeningSong":{"customTitle":"10"},"Duty_0123456789abcdef0123456789abcdef_1":{"personId":"sample","privateNote":"PERSON SECRET"}}},"people":[{"id":"sample","name":"Sample Duty Assignee","phone":"PRIVATE PHONE"},{"id":"unused","name":"UNASSIGNED PRIVATE PERSON"}]}')->>'token'),true);
select ca_feature_check.assert(public.get_oclm_public_snapshot(current_setting('ca_feature.snapshot_token'))->'snapshot'->'additionalDuties'->0->>'name'='Microphones','public metadata preserves safe duty definitions');
select ca_feature_check.assert(jsonb_array_length(public.get_oclm_public_snapshot(current_setting('ca_feature.snapshot_token'))->'snapshot'->'additionalDuties')=1,'invalid duty definitions are omitted');
select ca_feature_check.assert(public.get_oclm_public_snapshot(current_setting('ca_feature.snapshot_token'))::text not like '%SECRET%' and public.get_oclm_public_snapshot(current_setting('ca_feature.snapshot_token'))::text not like '%PRIVATE%' and public.get_oclm_public_snapshot(current_setting('ca_feature.snapshot_token'))::text not like '%INVALID DUTY%','publication strips private notes, contacts and unused people');
do $$ begin begin perform public.upsert_oclm_public_snapshot('feature-check-b','{}');raise exception 'Assistant published another congregation';exception when insufficient_privilege then null;end;end $$;
select ca_feature_check.assert(public.get_oclm_public_snapshot(current_setting('ca_feature.snapshot_token'))->'snapshot'->'additionalDuties'->0->>'section'='AV','public metadata preserves duty section');
select ca_feature_check.assert(public.get_oclm_public_snapshot(current_setting('ca_feature.snapshot_token'))->'snapshot'->'assignments'->'2026-W44'->'MeetingStart'->>'customTitle'='19:00','meeting details survive the public sanitizer');
reset role;rollback;
select 'PASS combined roles, limited assistants and private-field-safe Additional Duties publication' as result;
